/* 최근검색 풀 */
const recentSearchPool = [
  ["문화혜택", "서산 맛집 추천", "복지 혜택 신청"],
  ["교통정보", "서산시 행사", "서산 카페"],
  ["서산 명소", "전통시장", "주말 이벤트"],
  ["공원 위치", "체육시설", "노인복지관"],
  ["가족 여행지", "아이와 갈만한 곳", "주차장 위치"]
];

function getRandomList(prevList) {
  const candidates = recentSearchPool.filter(
    (arr) => arr.join("|") !== prevList.join("|")
  );
  if (candidates.length === 0) return prevList;
  const i = Math.floor(Math.random() * candidates.length);
  return candidates[i];
}

export default function AiSearch() {
  const [inputValue, setInputValue] = useState("");
  const [recentSearches, setRecentSearches] = useState(recentSearchPool[0]);

  /**
   * searchResult
   * - null  : 초기(인기 질문/카테고리 보임)
   * - false : 결과 없음(슬픈 말풍선)
   * - object: 결과 있음 { answer, sources }
   */
  const [searchResult, setSearchResult] = useState(null);
  const [tab, setTab] = useState("answer"); // 'answer' | 'sources'

  const handleAiSearch = () => {
    const q = inputValue.trim();
    if (!q) return;

    if (q.includes("없")) {
      setSearchResult(false);
      setTab("answer");
    } else {
      setSearchResult({
        answer:
          "서산시의 노인 복지에 대한 주요 내용은 다음과 같아요.\n\n" +
          "• 주요 복지 정책 및 사업\n" +
          "노인여가복지시설 지원: 경로당·마을회관 등 관내 시설을 대상으로 냉·난방비와 각종 물품을 지원하고 있어요.\n" +
          "노인 일자리 사업: 어르신들의 경제적 안정과 사회 참여를 돕기 위한 일자리를 제공합니다.\n\n" +
          "• 주요 복지 시설\n" +
          "서산노인복지센터, 서산노인전문요양센터 등에서 장기요양·방문요양 등 서비스를 제공하고 있어요.",
        sources: [
          {
            title: "충청남도 서산시_재가노인 복지시설",
            link: "#",
            provider: "충청남도 데이터포털 올담"
          },
          {
            title: "충청남도 서산시_노인의료복지시설",
            link: "#",
            provider: "충청남도 데이터포털 올담"
          }
        ]
      });
      setTab("answer");
    }

    setInputValue("");
  };

  const handleRefresh = () => {
    setRecentSearches((prevList) => getRandomList(prevList));
  };

  return (
    <div className={styles.bg}>
      {/* ======= 위에 검색 영역: 항상 고정 렌더 ======= */}
      <div className={styles.topSection}>
        <div className={styles.bgBox}>
          <div className={styles.aiSearchBalloonBox}>
            <img src={SearchBalloon} alt="검색 말풍선" className={styles.balloonBg} />
            <div className={styles.balloonContent}>
              <input
                className={styles.balloonInput}
                placeholder="찾으시는 소식이 있나요?"
                value={inputValue}
                onChange={(e) => setInputValue(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && handleAiSearch()}
              />
              <button
                className={styles.aiSearchRight}
                onClick={handleAiSearch}
                onKeyDown={(e) => e.key === "Enter" && handleAiSearch()}
              >
                <span className={styles.aiSearchBold}>AI 검색</span>
                <img src={SparkleIcon} alt="" className={styles.sparkleIcon} />
              </button>
            </div>
          </div>

          {/* 최근 검색 */}
          <div className={styles.buttonGroup}>
            <div className={styles.searchHistoryTitle}>
              <img
                src={History}
                alt="새로고침"
                className={styles.historyIcon}
                onClick={handleRefresh}
                onKeyDown={(e) =>
                  (e.key === "Enter" || e.key === " ") && handleRefresh()
                }
                tabIndex={0}
                aria-label="새로고침"
              />
              최근 검색
            </div>
            {recentSearches.map((item, idx) => (
              <button key={item + idx} className={styles.pillBtn}>
                {item}
              </button>
            ))}
          </div>
        </div>

        {/* 오른쪽 마스코트(장식) */}
        <img
          src={QuestionLogo}
          alt="logo"
          className={styles.questionLogo}
          draggable="false"
        />
      </div>

      {/* ======= 아래 영역: 결과가 있으면 결과, 없으면 초기 콘텐츠 ======= */}

      {/* 결과(답변/출처) */}
      {searchResult !== null && (
        <div className={styles.aiResultWrap}>
          <div className={styles.resultRow}>
            <img
              src={searchResult === false ? sadLogo : happyLogo}
              alt="마스코트"
              className={styles.resultLogo}
            />
            <img
              src={searchResult === false ? denyBubble : answerBubble}
              alt={searchResult === false ? "AI 답변이 불가능합니다" : "AI 답변이 완료되었습니다"}
              className={styles.resultBubbleImg}
            />
          </div>

          <div className={styles.tabs}>
            <button
              className={`${styles.tab} ${tab === "answer" ? styles.active : ""}`}
              onClick={() => setTab("answer")}
            >
              답변
            </button>
            <button
              className={`${styles.tab} ${tab === "sources" ? styles.active : ""}`}
              onClick={() => setTab("sources")}
            >
              출처
            </button>
          </div>

          {tab === "answer" ? (
            searchResult === false ? (
              <div className={styles.emptyWrap}>
                이런, 결과가 없습니다. 다시 시도해보세요.
              </div>
            ) : (
              <>
                <div className={styles.resultCardList}>
                  {searchResult.sources.map((item, idx) => (
                    <div className={styles.resultCard} key={idx}>
                      <div className={styles.resultCardTitle}>{item.title}</div>
                      <div className={styles.resultCardProvider}>{item.provider}</div>
                      <a
                        className={styles.resultCardLink}
                        href={item.link}
                        target="_blank"
                        rel="noopener noreferrer"
                      >
                        바로가기
                      </a>
                    </div>
                  ))}
                </div>
                <div className={styles.answerCard}>
                  {searchResult.answer.split("\n").map((line, i) => (
                    <p key={i} className={styles.answerText}>
                      {line}
                    </p>
                  ))}
                </div>
              </>
            )
          ) : (
            <div className={styles.srcList}>
              {searchResult === false ? (
                <div className={styles.srcEmpty}>표시할 출처가 없습니다.</div>
              ) : (
                searchResult.sources.map((s, idx) => (
                  <article key={idx} className={styles.srcItem}>
                    <div className={styles.srcRow}>
                      <div className={styles.srcNum}>{idx + 1}</div>
                      <div className={styles.srcMeta}>
                        <div className={styles.srcTitle}>{s.title}</div>
                        <div className={styles.srcOrg}>{s.provider}</div>
                        <a
                          href={s.link}
                          target="_blank"
                          rel="noopener noreferrer"
                          className={styles.srcLink}
                        >
                          링크 열기 ↗
                        </a>
                      </div>
                    </div>
                  </article>
                ))
              )}
            </div>
          )}
        </div>
      )}

      {/* 초기 콘텐츠(인기 질문/카테고리) */}
      {searchResult === null && (
        <div className={styles.contentsWrap}>
          {/* 인기질문 */}
          <div className={styles.section}>
            <div className={styles.sectionTitle}>
              <img src={LightbulbIcon} alt="" className={styles.titleIcon} />
              인기 질문
            </div>
            <div className={styles.grid}>
              {[
                { tag: "민원", text: "서산시청 민원 어떻게 넣어요?" },
                { tag: "민원", text: "서산시청 민원 어떻게 넣어요?" },
                { tag: "행사", text: "오늘 서산에 열리는 행사 뭐 있어?" },
                { tag: "행사", text: "오늘 서산에 열리는 행사 뭐 있어?" }
              ].map((q, i) => (
                <div key={i} className={styles.card}>
                  <div className={styles.cardTop}>
                    <span className={styles.tag}>{q.tag}</span>
                    <img src={ChatCircleDots} alt="" className={styles.cardIcon} />
                  </div>
                  <div className={styles.cardText}>{q.text}</div>
                </div>
              ))}
            </div>
          </div>

          {/* 인기카테고리 */}
          <div className={styles.section}>
            <div className={styles.sectionTitle}>
              <img src={LightningIcon} alt="" className={styles.titleIcon} />
              인기 카테고리
            </div>
            <div className={styles.gridCat}>
              <div className={styles.catCard}>
                <div>
                  <div className={styles.catTitle}>교통</div>
                  <div className={styles.catDesc}>
                    복잡한 서산시의 교통 노선,<br />
                    바로 알아보세요
                  </div>
                </div>
                <img src={BusIcon} alt="교통" className={styles.catImg} />
                <img src={BlackCircle} alt="arrow" className={styles.arrowIcon} />
              </div>
              <div className={styles.catCard}>
                <div>
                  <div className={styles.catTitle}>복지</div>
                  <div className={styles.catDesc}>
                    복지혜택, 찾기 힘드신가요?<br />
                    통합 정보를 확인하세요
                  </div>
                </div>
                <img src={HealthIcon} alt="복지" className={styles.catImg} />
                <img src={BlackCircle} alt="arrow" className={styles.arrowIcon} />
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
